//! The editor's JavaScript / DOM data (`data/js.data`, generated by `cargo xtask web-data` from
//! MDN's public-domain data): the built-in objects and the DOM interfaces with their
//! members, and whether each is deprecated, experimental or non-standard, with the
//! signatures from TypeScript's declarations. Embedded; parsed on first use.

use std::collections::HashMap;

static DATA: &str = include_str!("../data/js.data");

/// Global variables whose object is an instance of a DOM interface.
const INSTANCES: &[(&str, &str)] = &[
    ("document", "Document"),
    ("window", "Window"),
    ("navigator", "Navigator"),
    ("location", "Location"),
    ("history", "History"),
    ("localStorage", "Storage"),
    ("sessionStorage", "Storage"),
    ("performance", "Performance"),
    ("screen", "Screen"),
    ("crypto", "Crypto"),
];

#[derive(Debug, Default)]
pub struct Js {
    /// (name, flags) of the global objects / interfaces, in name order.
    pub globals: Vec<(&'static str, &'static str)>,
    members: HashMap<&'static str, Vec<(&'static str, &'static str)>>,
    /// (owner, member) → `(params): type` / `: type`; owner `""` for the globals (a
    /// function's or a constructor's).
    signatures: HashMap<(&'static str, &'static str), &'static str>,
    /// Member → the owners declaring it (for receivers whose type isn't known).
    owners: HashMap<&'static str, Vec<&'static str>>,
    /// The deprecated globals and (owner, member)s (looked up for each call of each version
    /// analysed).
    deprecated: std::collections::HashSet<(&'static str, &'static str)>,
}

impl Js {
    /// The heap it takes (its text is the binary's: only the tables).
    pub fn weight(&self) -> u64 {
        use kernel::memory::{map_bytes, vec_bytes};
        vec_bytes(&self.globals)
            + map_bytes(&self.members)
            + self.members.values().map(vec_bytes).sum::<u64>()
            + map_bytes(&self.signatures)
            + map_bytes(&self.owners)
            + self.owners.values().map(vec_bytes).sum::<u64>()
            + (self.deprecated.capacity() * std::mem::size_of::<(&str, &str)>()) as u64
    }
}

/// The data: read on first use, let go when unused for a while (the module's
/// `release_idle`), read again when needed.
pub static JS: kernel::cache::OnDemand<Js> = kernel::cache::OnDemand::new(load);

pub fn get() -> std::sync::Arc<Js> {
    JS.get()
}

fn load() -> Js {
    let mut js = Js::default();
    for line in DATA.lines().filter(|l| !l.starts_with('#')) {
        let mut f = line.split('\t');
        match (f.next(), f.next(), f.next(), f.next(), f.next()) {
            (Some("g"), Some(name), flags, sig, _) => {
                if flags.is_some_and(|f| f.contains('d')) {
                    js.deprecated.insert(("", name));
                }
                js.globals.push((name, flags.unwrap_or("")));
                if let Some(sig) = sig.filter(|s| !s.is_empty()) {
                    js.signatures.insert(("", name), sig);
                }
            }
            (Some("m"), Some(owner), Some(member), flags, sig) => {
                if flags.is_some_and(|f| f.contains('d')) {
                    js.deprecated.insert((owner, member));
                }
                js.members.entry(owner).or_default().push((member, flags.unwrap_or("")));
                if let Some(sig) = sig.filter(|s| !s.is_empty()) {
                    js.signatures.insert((owner, member), sig);
                    js.owners.entry(member).or_default().push(owner);
                }
            }
            _ => {}
        }
    }
    js
}

impl Js {
    /// The interface / object whose members follow `receiver.` (`document` → `Document`,
    /// `Math` → `Math`), if known.
    pub fn owner(&self, receiver: &str) -> Option<&'static str> {
        if let Some((_, interface)) = INSTANCES.iter().find(|(r, _)| *r == receiver) {
            return self.members.get_key_value(interface).map(|(k, _)| *k);
        }
        self.members.get_key_value(receiver).map(|(k, _)| *k)
    }

    pub fn members(&self, owner: &str) -> &[(&'static str, &'static str)] {
        self.members.get(owner).map_or(&[], Vec::as_slice)
    }

    /// The signature of `owner.member` (owner `""`: a global function / constructor).
    pub fn signature(&self, owner: &str, member: &str) -> Option<&'static str> {
        self.signatures.get(&(owner, member)).copied()
    }

    /// The owner and signature of `member` on an object of unknown type, when every
    /// interface declaring it agrees (`el.addEventListener` → `EventTarget`).
    pub fn any_signature(&self, member: &str) -> Option<(&'static str, &'static str)> {
        let owners = self.owners.get(member)?;
        let sig = self.signature(owners[0], member)?;
        owners.iter().all(|o| self.signature(o, member) == Some(sig)).then_some((owners[0], sig))
    }

    /// Global `name` (e.g. `escape`) is deprecated.
    pub fn global_deprecated(&self, name: &str) -> bool {
        self.deprecated.contains(&("", name))
    }

    /// Member `name` of `owner` (from [`Self::owner`]) is deprecated.
    pub fn member_deprecated(&self, owner: &str, name: &str) -> bool {
        self.deprecated.contains(&(owner, name))
    }

    /// The global variables that are instances (`document`, `window`…).
    pub fn instances(&self) -> impl Iterator<Item = &'static str> {
        INSTANCES.iter().map(|(name, _)| *name)
    }
}

